def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me, last_opp = history[-1]

    opp_c = sum(1 for a in opp if a == 'C')
    opp_rate = opp_c / n
    my_def_recent = sum(1 for a in me[-10:] if a == 'D')
    opp_def_recent = sum(1 for a in opp[-10:] if a == 'D')
    remaining = 100 - n

    # Endgame: defect in the last rounds to exploit or avoid being exploited.
    if remaining <= 2:
        return 'D'
    if remaining <= 5:
        return 'D'
    if remaining <= 15:
        if opp_rate > 0.6:
            return 'D'
        if last_opp == 'D':
            return 'D'

    # Count how often the opponent forgave our defections vs retaliated.
    forgive = 0
    retaliate = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if opp[i + 1] == 'C':
                forgive += 1
            else:
                retaliate += 1

    # If opponent defected last round.
    if last_opp == 'D':
        if last_me == 'C':
            # They defected, we cooperated. Punish, but forgive if they've been mostly cooperative.
            if opp_rate > 0.7 and n > 20:
                if rng.random() < 0.5:
                    return 'C'
            return 'D'
        else:
            # Both defected. Try to restore cooperation if opponent has been cooperative.
            if opp_rate > 0.7 and opp_def_recent <= 2:
                return 'C'
            return 'D'

    # Opponent cooperated last round.
    if last_me == 'D':
        # We defected and they cooperated. Never defect twice in a row against a cooperator.
        return 'C'

    # Both cooperated last round. Consider probing if opponent is very cooperative.
    if n > 10 and opp_rate > 0.8:
        if my_def_recent <= 1:
            # Probe probability based on forgiveness history.
            if forgive > retaliate * 2:
                prob = 0.4
            elif forgive > retaliate:
                prob = 0.2
            else:
                prob = 0.05
            if rng.random() < prob:
                return 'D'
        else:
            # We have defected recently. If opponent is very forgiving, continue exploiting.
            if forgive > retaliate * 3 and my_def_recent < 5:
                return 'D'

    return 'C'
